export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = [];
  let allThresholdsPassed = true;

  if (thresholds && typeof thresholds === 'object') {
    for (const [metricId, minScore] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const passed = metric && typeof metric.score === 'number' && metric.score >= minScore;
      const score = metric?.score ?? null;
      if (!passed) {
        allThresholdsPassed = false;
      }
      thresholdResults.push({
        metric: metricId,
        min: minScore,
        score,
        passed
      });
    }
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && typeof thresholds === 'object') {
    report.passed = allThresholdsPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

