10	const toArray = (values) => (Array.isArray(values) ? values : []);
11	const asString = (value) => {
12	  if (value == null) return '';
13	  if (typeof value === 'string') return value;
14	  if (typeof value === 'object') {
15	    if ('text' in value) return String(value.text ?? '');
16	    if ('output' in value) return String(value.output ?? '');
17	  }
18	  return String(value);
19	};
